"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  APR_GAP_PATH,
  DEBT_STOCK_PATH,
  DELINQUENCY_PATH,
  HEADLINE,
  LIQUID_CASH,
  SAVING_RATE_PATH,
  SOURCE_NOTE,
  SOURCES,
  debtStockTotalPath,
  fmtPct,
  fmtPp,
  fmtTn,
  latestDebtProductShares,
  rankedWealthByShare,
} from "@/data/consumer-finance-markets-research-2026-data";

// viz-types: saving-rate area, stacked debt composition, delinquency multi-line, wealth??delinquency scatter, liquid cash bars, APR-gap composed | layout: canvas

type Panel = "flows" | "debt" | "stress" | "allocate" | "pricing";
type RangeMode = "full" | "postcovid";
type StressMetric = "all" | "cards" | "secured";

const SAVE = "#14b8a6";
const MORT = "#0ea5e9";
const CARD = "#f43f5e";
const AUTO = "#f59e0b";
const STUD = "#a78bfa";
const WEALTH = "#38bdf8";
const GAP = "#fb7185";
const FUNDS = "#64748b";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-xs font-semibold transition ${
              value === o.id
                ? "bg-teal-800 text-white"
                : "text-slate-600 hover:bg-slate-100"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function ConsumerFinanceMarketsResearchDashboard() {
  const [panel, setPanel] = useState<Panel>("flows");
  const [range, setRange] = useState<RangeMode>("full");
  const [stress, setStress] = useState<StressMetric>("all");

  const savingRows = useMemo(() => {
    const rows =
      range === "postcovid"
        ? SAVING_RATE_PATH.filter((d) => d.sortKey >= 2021)
        : SAVING_RATE_PATH;
    return rows.map((d) => ({
      label: d.label,
      rate: d.savingRatePct,
    }));
  }, [range]);

  const debtStacked = useMemo(() => {
    const rows =
      range === "postcovid"
        ? DEBT_STOCK_PATH.filter((d) => d.year >= 2021)
        : DEBT_STOCK_PATH;
    return rows.map((d) => ({
      year: String(d.year),
      Mortgage: d.mortgageTn,
      HELOC: d.helocTn,
      Auto: d.autoTn,
      Cards: d.creditCardTn,
      Student: d.studentTn,
      Other: d.otherTn,
    }));
  }, [range]);

  const debtTotals = useMemo(() => {
    const rows = debtStockTotalPath();
    return range === "postcovid" ? rows.filter((d) => d.year >= 2021) : rows;
  }, [range]);

  const delinqRows = useMemo(() => {
    const rows =
      range === "postcovid"
        ? DELINQUENCY_PATH.filter((d) => d.year >= 2021)
        : DELINQUENCY_PATH;
    return rows.map((d) => ({
      year: d.label,
      Mortgage: d.mortgage,
      Auto: d.auto,
      Cards: d.creditCard,
      Student: d.student,
    }));
  }, [range]);

  const productShares = useMemo(() => latestDebtProductShares(), []);
  const wealthBars = useMemo(() => rankedWealthByShare(), []);

  const scatterPts = useMemo(() => {
    let pts = productShares.map((p) => ({
      name: p.shortLabel,
      share: p.sharePct,
      delinq: p.delinq90Pct,
      tn: p.tn,
      id: p.id,
    }));
    if (stress === "cards") pts = pts.filter((p) => p.id === "card" || p.id === "other");
    if (stress === "secured")
      pts = pts.filter((p) => p.id === "mortgage" || p.id === "heloc" || p.id === "auto");
    return pts;
  }, [productShares, stress]);

  const aprRows = useMemo(() => {
    const rows =
      range === "postcovid"
        ? APR_GAP_PATH.filter((d) => d.year >= 2021)
        : APR_GAP_PATH;
    return rows.map((d) => ({
      year: d.label,
      CardAPR: d.cardAprPct,
      FedFunds: d.fedFundsPct,
      Gap: d.gapPp,
    }));
  }, [range]);

  const liquidBars = useMemo(
    () =>
      LIQUID_CASH.map((r) => ({
        name: r.label.replace(" (ex-large time)", "").replace(" (est.)", ""),
        tn: r.tn,
        yieldPct: r.yieldPct,
      })),
    [],
  );

  return (
    <div className="w-full space-y-4">
      <div className="rounded-xl border border-teal-900/20 bg-gradient-to-br from-slate-900 via-teal-950 to-slate-900 px-5 py-5 text-white shadow-sm sm:px-6">
        <p className="text-xs font-semibold uppercase tracking-widest text-teal-200/80">
          Household balance sheets ??? save, borrow, allocate
        </p>
        <h2 className="mt-1 text-xl font-bold tracking-tight sm:text-2xl">
          {fmtTn(HEADLINE.totalHouseholdDebtTn)} in household debt ?? saving rate{" "}
          {fmtPct(HEADLINE.personalSavingRatePct)} ?? cards delinquent at{" "}
          {fmtPct(HEADLINE.cardDelinq90Pct)}
        </h2>
        <p className="mt-2 max-w-3xl text-sm text-teal-50/85">
          After the pandemic saving spike ({fmtPct(HEADLINE.peakSavingRate2021Pct)} peak), US
          households run a ~{fmtPct(HEADLINE.personalSavingRatePct)} flow while carrying{" "}
          {fmtTn(HEADLINE.totalHouseholdDebtTn)} of debt ??? mortgages still ~{HEADLINE.mortgageSharePct}%
          of the book, but stress shows up in revolving credit. Net worth near{" "}
          {fmtTn(HEADLINE.householdNetWorthTn, 0)} sits mostly in equities and housing, not
          checking accounts.
        </p>
        <div className="mt-4 flex flex-wrap gap-3 text-xs text-teal-100/90">
          <span className="rounded-md bg-white/10 px-2.5 py-1">
            Card APR {fmtPct(HEADLINE.cardAprPct)} vs funds {fmtPct(HEADLINE.fedFundsPct)} (
            {fmtPp(HEADLINE.aprGapPp)} gap)
          </span>
          <span className="rounded-md bg-white/10 px-2.5 py-1">
            Liquid cash: deposits {fmtTn(HEADLINE.depositsCashTn, 1)} ?? MMFs{" "}
            {fmtTn(HEADLINE.mmfCashTn)}
          </span>
          <span className="rounded-md bg-white/10 px-2.5 py-1">
            Mortgage 90+ delinq {fmtPct(HEADLINE.mortgageDelinq90Pct)}
          </span>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-3">
        <ToggleGroup<Panel>
          label="Panel"
          value={panel}
          onChange={setPanel}
          options={[
            { id: "flows", label: "Saving flows" },
            { id: "debt", label: "Debt stock" },
            { id: "stress", label: "Delinquency" },
            { id: "allocate", label: "Allocation" },
            { id: "pricing", label: "Card pricing" },
          ]}
        />
        <ToggleGroup<RangeMode>
          label="Range"
          value={range}
          onChange={setRange}
          options={[
            { id: "full", label: "2019???2026" },
            { id: "postcovid", label: "Post-COVID" },
          ]}
        />
        {panel === "stress" && (
          <ToggleGroup<StressMetric>
            label="Products"
            value={stress}
            onChange={setStress}
            options={[
              { id: "all", label: "All products" },
              { id: "cards", label: "Revolving" },
              { id: "secured", label: "Secured" },
            ]}
          />
        )}
      </div>

      {panel === "flows" && (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="Personal saving rate"
            subtitle="BEA NIPA ??? seasonally adjusted annual rate (% of disposable income)"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={savingRows}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip />
                  <Area
                    type="monotone"
                    dataKey="rate"
                    name="Saving rate"
                    stroke={SAVE}
                    fill={SAVE}
                    fillOpacity={0.25}
                    strokeWidth={2}
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Debt stock totals"
            subtitle="NY Fed household debt balances ??? total and major buckets ($T)"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={debtTotals}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Bar dataKey="mortgageTn" name="Mortgage" fill={MORT} stackId="a" />
                  <Bar dataKey="revolvingTn" name="Cards+HELOC" fill={CARD} stackId="a" />
                  <Bar dataKey="installmentTn" name="Auto+student+other" fill={AUTO} stackId="a" />
                  <Line
                    type="monotone"
                    dataKey="totalTn"
                    name="Total"
                    stroke="#0f172a"
                    strokeWidth={2}
                    dot={false}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {panel === "debt" && (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="Debt composition over time"
            subtitle="Stacked product balances ($T) ??? mortgages dominate the level, cards dominate the stress narrative"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={debtStacked}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Area type="monotone" dataKey="Mortgage" stackId="1" stroke={MORT} fill={MORT} fillOpacity={0.85} />
                  <Area type="monotone" dataKey="Student" stackId="1" stroke={STUD} fill={STUD} fillOpacity={0.85} />
                  <Area type="monotone" dataKey="Auto" stackId="1" stroke={AUTO} fill={AUTO} fillOpacity={0.85} />
                  <Area type="monotone" dataKey="Cards" stackId="1" stroke={CARD} fill={CARD} fillOpacity={0.85} />
                  <Area type="monotone" dataKey="HELOC" stackId="1" stroke="#94a3b8" fill="#94a3b8" fillOpacity={0.85} />
                  <Area type="monotone" dataKey="Other" stackId="1" stroke="#cbd5e1" fill="#cbd5e1" fillOpacity={0.85} />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Latest product shares"
            subtitle={`${HEADLINE.asOfDebt} ??? balance ($T) with 90+ day delinquency rate`}
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={productShares}
                  layout="vertical"
                  margin={{ left: 8, right: 12 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis type="category" dataKey="shortLabel" width={72} tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Bar dataKey="tn" name="Balance ($T)" radius={[0, 4, 4, 0]}>
                    {productShares.map((p) => (
                      <Cell
                        key={p.id}
                        fill={
                          p.id === "mortgage"
                            ? MORT
                            : p.id === "card"
                              ? CARD
                              : p.id === "auto"
                                ? AUTO
                                : p.id === "student"
                                  ? STUD
                                  : "#64748b"
                        }
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {panel === "stress" && (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="90+ day delinquency transitions"
            subtitle="NY Fed ??? % of balance newly 90+ days delinquent (product split)"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={delinqRows}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip />
                  {(stress === "all" || stress === "secured") && (
                    <Line type="monotone" dataKey="Mortgage" stroke={MORT} strokeWidth={2} dot={false} />
                  )}
                  {(stress === "all" || stress === "secured") && (
                    <Line type="monotone" dataKey="Auto" stroke={AUTO} strokeWidth={2} dot={false} />
                  )}
                  {(stress === "all" || stress === "cards") && (
                    <Line type="monotone" dataKey="Cards" stroke={CARD} strokeWidth={2.5} />
                  )}
                  {stress === "all" && (
                    <Line type="monotone" dataKey="Student" stroke={STUD} strokeWidth={2} strokeDasharray="4 4" />
                  )}
                </LineChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Size vs stress map"
            subtitle="Bubble = product balance ($T); x = share of book; y = 90+ delinquency"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ left: 8, right: 12, top: 8, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="share"
                    name="Share"
                    unit="%"
                    tick={{ fontSize: 11 }}
                    domain={[0, "auto"]}
                  />
                  <YAxis
                    type="number"
                    dataKey="delinq"
                    name="90+ %"
                    unit="%"
                    tick={{ fontSize: 11 }}
                  />
                  <ZAxis type="number" dataKey="tn" range={[80, 400]} />
                  <Tooltip cursor={{ strokeDasharray: "3 3" }} />
                  <Scatter name="Products" data={scatterPts} fill={CARD}>
                    {scatterPts.map((p) => (
                      <Cell
                        key={p.id}
                        fill={
                          p.id === "mortgage"
                            ? MORT
                            : p.id === "card"
                              ? CARD
                              : p.id === "auto"
                                ? AUTO
                                : p.id === "student"
                                  ? STUD
                                  : "#64748b"
                        }
                      />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {panel === "allocate" && (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="Where household wealth sits"
            subtitle="Fed Z.1-style asset shares of ~$169T household net worth (latest anchors)"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={wealthBars} layout="vertical" margin={{ left: 8, right: 16 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} unit="%" />
                  <YAxis type="category" dataKey="shortLabel" width={96} tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Bar dataKey="sharePct" name="Share of wealth" fill={WEALTH} radius={[0, 4, 4, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Liquid cash parking"
            subtitle="Deposits vs MMFs vs estimated short Treasuries ??? stock ($T) and indicative yields"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={liquidBars}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{ fontSize: 10 }} interval={0} />
                  <YAxis yAxisId="left" tick={{ fontSize: 11 }} />
                  <YAxis yAxisId="right" orientation="right" tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip />
                  <Bar yAxisId="left" dataKey="tn" name="Stock ($T)" fill={SAVE} radius={[4, 4, 0, 0]} />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="yieldPct"
                    name="Yield %"
                    stroke={GAP}
                    strokeWidth={2}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {panel === "pricing" && (
        <ChartCard
          title="Credit-card APR vs fed funds"
          subtitle="Sticky ~21% card APRs widen the gap even as policy rates ease ??? borrowing cost stays elevated"
        >
          <div className="h-80 w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={aprRows}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                <YAxis tick={{ fontSize: 11 }} unit="%" />
                <Tooltip />
                <Bar dataKey="Gap" name="APR ??? funds (pp)" fill={GAP} opacity={0.35} />
                <Line type="monotone" dataKey="CardAPR" name="Card APR" stroke={CARD} strokeWidth={2.5} />
                <Line type="monotone" dataKey="FedFunds" name="Fed funds" stroke={FUNDS} strokeWidth={2} />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      <div className="rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-xs text-slate-600">
        <p className="font-semibold text-slate-800">Sources & method</p>
        <p className="mt-1">{SOURCE_NOTE}</p>
        <ul className="mt-2 list-inside list-disc space-y-0.5">
          {SOURCES.map((s) => (
            <li key={s.url}>
              <a
                href={s.url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-teal-800 underline-offset-2 hover:underline"
              >
                {s.label}
              </a>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  APR_GAP_PATH,
  DEBT_STOCK_PATH,
  DELINQUENCY_PATH,
  HEADLINE,
  LIQUID_CASH,
  SAVING_RATE_PATH,
  SOURCE_NOTE,
  SOURCES,
  debtStockTotalPath,
  fmtPct,
  fmtPp,
  fmtTn,
  latestDebtProductShares,
  rankedWealthByShare,
} from "@/data/consumer-finance-markets-research-2026-data";

// viz-types: saving-rate area, stacked debt composition, delinquency multi-line, wealth??delinquency scatter, liquid cash bars, APR-gap composed | layout: canvas

type Panel = "flows" | "debt" | "stress" | "allocate" | "pricing";
type RangeMode = "full" | "postcovid";
type StressMetric = "all" | "cards" | "secured";

const SAVE = "#14b8a6";
const MORT = "#0ea5e9";
const CARD = "#f43f5e";
const AUTO = "#f59e0b";
const STUD = "#a78bfa";
const WEALTH = "#38bdf8";
const GAP = "#fb7185";
const FUNDS = "#64748b";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
